"""Reusable evidence-first laundry calculator on two existing URLs."""
import re
from html import escape
DE='/waeschetrockner-oder-luftentfeuchter.html'
EN='/en/guide/dehumidifier-drying-clothes-cost.html'
SOURCE='https://www.verbraucherzentrale.de/wissen/energie/strom-sparen/beim-kauf-eines-waeschetrockners-an-den-stromverbrauch-denken-37984'
def block(en=False):
 def t(de,en_text):return en_text if en else de
 def field(name,label,value,lo,hi):return f'<label>{label}<input name="{name}" type="number" value="{value}" min="{lo}" max="{hi}" step="any" required inputmode="decimal"></label>'
 def select(name,label,choices):return f'<label>{label}<select name="{name}">'+''.join(f'<option value="{v}">{s}</option>' for v,s in choices)+'</select></label>'
 intro=t('Kleine Wattzahl. Lange Laufzeit. Was kostet eine wirklich trockene Ladung?','Low watts. Long runtime. What does one equally dry load cost?')
 example=t('Beispiel laden: 250 W, 8 Stunden','Load example: 250 W, 8 hours')
 dryer=field('dryer',t('Trockner: Verbrauch laut Messung oder Label','Dryer: meter reading or label value'),1.5,0,2000)+select('dryerBasis',t('Einheit der Trockner-Angabe','Dryer value is per'),[('cycle',t('kWh je Ladung','load (kWh)')),('hundred',t('kWh je 100 Zyklen','100 cycles (kWh)'))])
 dehum=select('method',t('Entfeuchter: Berechnungsgrundlage','Dehumidifier: calculation method'),[('estimate',t('Mittlere Watt × Stunden schätzen','Estimate average watts × hours')),('measured',t('Gemessene kWh je Durchgang','Measured kWh per run'))])
 dehum+='<div data-estimate class="lc-grid">'+field('watts',t('Mittlere Leistung (W)','Average power (W)'),250,0,5000)+field('hours',t('Laufzeit je Durchgang (h)','Runtime per run (h)'),8,0,72)+'</div><div data-measured hidden>'+field('dehum',t('Gemessene Energie je Durchgang (kWh)','Metered energy per run (kWh)'),2,0,100)+'</div>'
 return '<!--EB_LAUNDRY-->'+f'''<link rel="stylesheet" href="/assets/laundry-check.css"><section class="eb-laundry" id="laundry-check" data-lang="{'en' if en else 'de'}" aria-labelledby="lc-title"><p class="lc-kicker">{t('Deine Wäsche. Deine Rechnung.','Your laundry. Your numbers.')}</p><h2 id="lc-title">{t('Trocknungskosten pro Ladung vergleichen','Compare drying cost per load')}</h2><p>{intro}</p><p class="lc-note">{t('Vorbelegte Zahlen sind ein frei gewähltes Beispiel, keine Messung oder Tarifempfehlung.','Prefilled numbers are a fictional example, not a measurement or recommended tariff.')}</p><button type="button" class="lc-secondary" data-example>{example}</button><form data-laundry><div class="lc-grid"><fieldset><legend>1 · {t('Trockner','Tumble dryer')}</legend>{dryer}</fieldset><fieldset><legend>2 · {t('Entfeuchter','Dehumidifier')}</legend>{dehum}</fieldset></div><details><summary>{t('Strompreis, Nutzung und Kaufpreis anpassen','Adjust tariff, usage and purchase cost')}</summary><div class="lc-grid">{field('price',t('Strompreis je kWh','Electricity unit price per kWh'),.35,0,5)}{select('currency',t('Währung · keine Umrechnung','Currency · no conversion'),[('EUR','EUR'),('GBP','GBP'),('USD','USD')])}{field('loads',t('Ladungen pro Woche','Loads per week'),3,0,30)}{field('purchase',t('Zusätzlicher Kaufpreis Entfeuchter','Extra upfront cost for dehumidifier'),0,0,50000)}</div></details><label class="lc-confirm"><input name="comparable" type="checkbox">{t('Gleiche Wäschemenge und gleicher Trocknungsgrad; die Annahmen passen zu beiden Verfahren.','Same laundry amount and final dryness; these assumptions fit both methods.')}</label><button type="submit">{t('Meine Kosten vergleichen','Compare my costs')}</button><p class="lc-error" role="alert" data-error></p></form><div class="lc-results" data-results hidden tabindex="-1" aria-labelledby="lc-result-title"><p class="lc-kicker" data-provenance></p><h3 id="lc-result-title">{t('Direkte Stromkosten je Ladung','Direct electricity cost per load')}</h3><div class="lc-bars"><div><span>{t('Trockner','Dryer')}</span><span class="lc-track"><i class="lc-bar" data-bar="dryer"></i></span><strong data-cost="dryer"></strong></div><div><span>{t('Entfeuchter','Dehumidifier')}</span><span class="lc-track"><i class="lc-bar" data-bar="dehum"></i></span><strong data-cost="dehum"></strong></div></div><p class="lc-verdict" data-verdict></p><p data-annual></p><p data-breakeven></p><p data-payback></p><p class="lc-detail" data-formula></p><p class="lc-note">{t('Raumheizung, Lüftungswärme, Reparaturen und Zeit fehlen. Ein trockener Raum beweist keine gleich trockene Wäsche.','Room heating, ventilation heat, repairs and your time are excluded. A dry room does not prove equally dry clothes.')}</p><button type="button" data-card>{t('Ergebniskarte als PNG','Download result card (PNG)')}</button><button type="button" class="lc-secondary" data-csv>{t('Rechenblatt als CSV','Download calculation (CSV)')}</button><p class="lc-status" role="status" data-export-status></p></div><details><summary>{t('Eine Ladung fair messen: Checkliste','Measure one load fairly: checklist')}</summary><ol><li>{t('Vergleiche Wäsche mit gleicher Masse, Schleuderdrehzahl und gewünschter Restfeuchte.','Use the same laundry mass, spin speed and desired final dryness.')}</li><li>{t('Notiere Start- und Endstand eines passenden Strommessgeräts sowie die Laufzeit. Beachte Anleitung und elektrische Belastbarkeit.','Record start/end energy readings and runtime using a suitable meter. Follow its instructions and electrical rating.')}</li><li>{t('Nutze die kWh-Differenz des ganzen Durchgangs. Typenschild-Watt ist keine gemessene mittlere Leistung.','Use the kWh difference for the whole run. Rated watts are not measured average power.')}</li><li>{t('Bei einem Label je 100 Zyklen: durch 100 teilen. Das Labelprogramm kann von deiner eigenen Nutzung abweichen.','For a label per 100 cycles, divide by 100. Its test programme may differ from your actual use.')}</li></ol></details><div class="lc-evidence"><p><strong>{t('Was hier belegt ist','What is supported here')}</strong><br>{t('Rechenweg: kWh × Strompreis. Vergleichsdaten: deine Eingaben. Geräteleistung: hier nicht getestet.','Method: kWh × unit price. Comparison data: your inputs. Device performance: not tested here.')}</p><p><a href="{SOURCE}">{t('Verbraucherzentrale: Label je 100 Trocknungen','Verbraucherzentrale: label per 100 drying cycles')}</a> · {t('geprüft 01.10.2026','checked 1 October 2026')}</p></div><p><a data-laundry-next href="{'/en/guide/dehumidifier-20-sqm.html#eb-moisture-choice' if en else '/guide/luftentfeuchter-ratgeber.html#eb-moisture-choice'}">{t('Danach prüfen: Brauche ich ein Gerät?','Next: do I need a dehumidifier?')}</a></p><button type="button" class="lc-secondary" data-share>{t('Rechnerlink kopieren','Copy calculator link')}</button><p class="lc-share-url" data-share-url></p><p class="lc-note">{t('Kein Konto. Eingaben bleiben im Browser. Downloads enthalten deine Zahlen; der geteilte Link enthält sie nicht. Anonyme Ereignisse zählen Nutzung, keine Messwerte.','No account. Inputs stay in your browser. Downloads contain your numbers; the shared link does not. Anonymous events count actions, not meter readings.')}</p><noscript><p>{t('Eigene Werte benötigen JavaScript. Beispiel: 250 W × 8 h ÷ 1.000 = 2 kWh; bei 0,35 €/kWh sind das 0,70 €. Ein Trockner mit 1,5 kWh kostet 0,525 €. Gleiche Trocknung vorausgesetzt.','Custom calculations need JavaScript. Example: 250 W × 8 h ÷ 1,000 = 2 kWh; at EUR 0.35/kWh that costs EUR 0.70. A dryer using 1.5 kWh costs EUR 0.525. Equal drying is assumed.')}</p></noscript></section><script type="module" src="/assets/laundry-check.mjs"></script><!--/EB_LAUNDRY-->'''
def inject(html,slug,en=False):
 if (en and slug=='dehumidifier-drying-clothes-cost') or (not en and slug=='waeschetrockner-oder-luftentfeuchter'):
  if '<!--EB_LAUNDRY-->' in html:return re.sub(r'<!--EB_LAUNDRY-->.*?<!--/EB_LAUNDRY-->',lambda _:block(en),html,flags=re.S)
  if not en:return re.sub(r'<section class="work-panel" aria-labelledby="calculator">.*?</section>',lambda _:block(False),html,count=1,flags=re.S).replace('href="#calculator"','href="#laundry-check"')
  if '<!--EB_BUYER-->' in html:return html.replace('<!--EB_BUYER-->',block(True)+'\n<!--EB_BUYER-->',1)
  return html.replace('<h2',block(True)+'\n<h2',1)
 return html
